@RestController
class ProjectController(private val projects: ProjectService) {
  @GetMapping("/projects/{id}")
  fun get(@PathVariable id: UUID): ProjectDto {
    val p = projects.repo.findById(id).orElseThrow()
    return ProjectDto(p.id, p.name, if (p.archivedAt != null) "ARCHIVED" else "ACTIVE")
  }
}
